// ResourceMemoryFlags Flags describing a memory allocation.
type ResourceMemoryFlags int32

const (
	MemoryFlagNone       ResourceMemoryFlags = 0    // Empty flag.
	MemoryFlagModule     ResourceMemoryFlags = 0x1  // Specifies that the allocation is static scoped to a module.
	MemoryFlagManaged    ResourceMemoryFlags = 0x2  // Specifies that the allocation is managed memory.
	MemoryFlagHostMapped ResourceMemoryFlags = 0x4  // Species that the allocation accessible from the host.
	MemoryFlagHostPinned ResourceMemoryFlags = 0x8  // Specifies that the allocation is pinned on the host.
	MemoryFlagPeer       ResourceMemoryFlags = 0x10 // Specifies that the allocation is located on a peer GPU.
	// MemoryFlagPeerAtomic: Specifies that the allocation is located on a peer GPU supporting native atomics. This implies that [MemoryFlagPeer] is set as well.
	MemoryFlagPeerAtomic ResourceMemoryFlags = 0x20
	// MemoryFlagCgRuntime: Specifies that the allocation is used by the Cooperative Groups runtime functions.
	MemoryFlagCgRuntime ResourceMemoryFlags = 0x40
	// MemoryFlagCnp: Specifies that this is an allocation used for CUDA Dynamic Parallelism purposes.
	MemoryFlagCnp      ResourceMemoryFlags = 0x80
	MemoryFlagForceInt ResourceMemoryFlags = 0x7fffffff
)

func (e ResourceMemoryFlags) String() string {
	switch e {
	case MemoryFlagNone:
		return "MemoryFlagNone"
	case MemoryFlagModule:
		return "MemoryFlagModule"
	case MemoryFlagManaged:
		return "MemoryFlagManaged"
	case MemoryFlagHostMapped:
		return "MemoryFlagHostMapped"
	case MemoryFlagHostPinned:
		return "MemoryFlagHostPinned"
	case MemoryFlagPeer:
		return "MemoryFlagPeer"
	case MemoryFlagPeerAtomic:
		return "MemoryFlagPeerAtomic"
	case MemoryFlagCgRuntime:
		return "MemoryFlagCgRuntime"
	case MemoryFlagCnp:
		return "MemoryFlagCnp"
	case MemoryFlagForceInt:
		return "MemoryFlagForceInt"
	}
	return fmt.Sprintf("ResourceMemoryFlags(%d)", e)
}

